<template><div class="page"><div class="page-head"><div><h1 class="page-title">用户标签</h1><div class="page-subtitle">管理微信侧标签并批量应用到粉丝</div></div><el-button type="primary" @click="edit({})">新建标签</el-button></div><div class="surface table-surface"><el-table :data="list" v-loading="loading"><el-table-column prop="id" label="ID" width="100"/><el-table-column prop="name" label="标签名称"/><el-table-column prop="count" label="粉丝数"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-popconfirm title="确定删除该标签？" @confirm="remove(row.id)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="form.id?'编辑标签':'新建标签'" width="420"><el-input v-model="form.name" placeholder="标签名称"/><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';const list=ref([]),loading=ref(false),dialog=ref(false),form=reactive({id:null,name:''});async function load(){loading.value=true;try{list.value=(await api.tags()).list||[]}finally{loading.value=false}}function edit(row){form.id=row.id||null;form.name=row.name||'';dialog.value=true}async function save(){await api.saveTag(form);dialog.value=false;ElMessage.success('已保存');load()}async function remove(id){await api.deleteTag(id);ElMessage.success('已删除');load()}onMounted(load)</script>
